import styled from 'styled-components';

import Animations from '@dynatrace/strato-design-tokens/animations';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { LOADING_STATE_OPACITY } from './constants.js';
import { isVertical } from './functions/orientation.js';
import type { Orientation } from '../../../../core/types/orientation.js';

// 3px size of the resizer + 6px of margins
export const DEFAULT_RESIZER_WRAPPER_SIZE = 15;
const RESIZER_SIZE = { width: '3px', height: '36px' };

export const StyledLegendWrapper = /* @__PURE__ */ styled('div')<{
  orientation: Orientation;
  $loading: boolean;
}>(({ orientation, $loading }) => ({
  gridArea: !isVertical(orientation) ? 'verticalLegend' : 'horizontalLegend',
  height: '100%',
  filter: $loading ? `opacity(${LOADING_STATE_OPACITY}%)` : 'none',
}));

export const StyledResizeContainer = /* @__PURE__ */ styled('div')<{
  isHorizontal: boolean;
  $loading: boolean;
}>(({ isHorizontal, $loading }) => ({
  display: 'flex',
  alignItems: 'center',
  justifyContent: isHorizontal ? 'flex-end' : 'center',
  height: isHorizontal ? 'inherit' : `${RESIZER_SIZE}px`,
  width: !isHorizontal ? 'inherit' : `${RESIZER_SIZE}px`,
  gridArea: isHorizontal ? 'horizontalResize' : 'verticalResize',
  filter: $loading ? `opacity(${LOADING_STATE_OPACITY}%)` : 'none',
}));
export const StyledLegendResizeLine = /* @__PURE__ */ styled('div')<{
  isHorizontal: boolean;
}>(({ isHorizontal }) => ({
  height: isHorizontal ? RESIZER_SIZE.height : RESIZER_SIZE.width,
  width: isHorizontal ? RESIZER_SIZE.width : RESIZER_SIZE.height,
  background: Colors.Border.Neutral.Accent,

  transitionDuration: Animations.Open.Duration.Fast,
  transitionTimingFunction: Animations.ExpandCollapse.Easing,
  transitionProperty: 'border-color, transform, top, bottom',

  transformOrigin: 'center center',
  alignSelf: isHorizontal ? 'center' : 'flex-end',
  justifySelf: 'center',
  borderRadius: Spacings.Size8,
  margin: isHorizontal ? `0 ${Spacings.Size6}` : `${Spacings.Size6} 0`,
  touchAction: 'none',
  cursor: isHorizontal ? 'col-resize' : 'row-resize',
  gridArea: isHorizontal ? 'horizontalResize' : 'verticalResize',
  '&:hover': {
    background: Colors.Border.Primary.Accent,
    transform: isHorizontal
      ? 'scaleX(1.2) scaleY(1.1)'
      : 'scaleX(1.1) scaleY(1.2)',
  },
}));
export const StyledGraphWrapper = /* @__PURE__ */ styled('div')<{
  $loading: boolean;
}>(({ $loading }) => ({
  minWidth: 0,
  gridArea: 'graphArea',
  filter: $loading ? `opacity(${LOADING_STATE_OPACITY}%)` : 'none',
}));

export const containerTemplateResizable = '1fr min-content min-content';
export const containerTemplateFixed = '1fr min-content';
export const fixedTemplateArea =
  '"graphArea verticalLegend" "horizontalLegend horizontalLegend"';
export const resizableTemplateArea =
  '"graphArea horizontalResize verticalLegend" "verticalResize . ." "horizontalLegend horizontalLegend horizontalLegend"';
